#!/usr/bin/env python3
"""Regenerates the synthetic icon pack in pack/ used by tests/test_visuals_icons.py.

Every image is drawn here from a few numbers with the standard library (zlib + struct), so the
fixture is original work and the tests never need a real, paid pack. Output is deterministic:
running this again produces byte-identical files.

  python3 tests/fixtures/visuals-icons/make_fixture.py
"""
import struct
import zlib
from pathlib import Path

PACK = Path(__file__).resolve().parent / "pack"


def chunk(kind: bytes, data: bytes) -> bytes:
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)


def png(width: int, height: int, rgb) -> bytes:
    """An RGBA PNG: a filled disc of `rgb` on a transparent background."""
    rows = bytearray()
    cx, cy, radius = (width - 1) / 2, (height - 1) / 2, min(width, height) / 2
    for y in range(height):
        rows.append(0)
        for x in range(width):
            inside = (x - cx) ** 2 + (y - cy) ** 2 <= radius ** 2
            rows += bytes((*rgb, 255)) if inside else b"\x00\x00\x00\x00"
    header = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header) + chunk(b"IDAT", zlib.compress(bytes(rows), 9)) + chunk(b"IEND", b"")


SVG = (
    '<?xml version="1.0" encoding="UTF-8"?>\n'
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">\n'
    '  <path d="M5 5 L19 19 M19 5 L5 19" stroke="#E5484D" stroke-width="3" stroke-linecap="round" fill="none"/>\n'
    "</svg>\n"
)

FILES = {
    "Currency/Coin Gold.png": png(16, 16, (240, 190, 40)),
    "Currency/gem_blue.png": png(32, 32, (60, 140, 250)),
    "Pets/coin gold.png": png(16, 16, (250, 220, 90)),
    "UI/Buttons/Arrow-Left.png": png(24, 24, (255, 255, 255)),
    "UI/Buttons/close.svg": SVG.encode("utf-8"),
    "UI/close.png": png(8, 8, (229, 72, 77)),
    "Weapons/Sword (2).png": png(48, 16, (180, 190, 200)),
    "Weapons/sword.png": png(16, 48, (200, 210, 220)),
    "star.png": png(64, 64, (255, 210, 60)),
    "LICENSE.txt": (
        "Synthetic test fixture for UltimateRobloxKit (tests/fixtures/visuals-icons).\n"
        "These images are generated by make_fixture.py and are part of the kit under its MIT licence.\n"
        "This is NOT a real icon pack and contains no third-party artwork.\n"
    ).encode("utf-8"),
    "notes.txt": b"Not an icon: the importer copies it and the registry leaves it out.\n",
}


def main() -> int:
    for rel, data in FILES.items():
        path = PACK / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    print("%d fixture files -> %s" % (len(FILES), PACK))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
